rb_destroy(rb);
rb = rb_create(4);
uint8_t a[] = {1, 2, 3, 4};
rb_write(rb, a, 4);
uint8_t b[] = {5, 6};
rb_write(rb, b, 2); /* overwrites 1,2; buffer has [3,4,5,6] */
uint8_t result[6];
r = rb_read(rb, result, 6);
CHECK(r == 4, "read after overwrite");
